export function useVal(flag: boolean) {
  const count = $state(0)
  switch (flag) {
    case true:
      return count
    default:
      return count
  }
}

export function useCond(flag: boolean) {
  const count = $state(0)
  return flag ? count : count
}

import { $memo, $state } from 'fict'

export function useConditional(flag: boolean) {
  const count = $state(0)
  const other = $state(1)
  return flag ? count : other
}

export function useLogical() {
  const count = $state(0)
  return true && count
}

export function useSequence() {
  const count = $state(0)
  return (0, count)
}

export function useIife() {
  const count = $state(0)
