export function useObjectSlot(flag: boolean) {
  const count = $state(0)
  const doubled = $memo(() => count() * 2)
  return { value: flag ? count : count, doubled: (0, doubled) }
}

export function useMixed(flag: boolean) {
  const count = $state(0)
  return flag && count
}

