type Todo = { id: number; text: string }

export let api: {
  rotate(): void
  prepend(): void
  dropSecond(): void
}

export function App() {
  let todos = $state<Todo[]>([
    { id: 1, text: 'wake up' },
    { id: 2, text: 'hydrate' },
    { id: 3, text: 'ship code' },
  ])

  api = {
    rotate() {
      if (todos.length < 2) return
      const [first, ...rest] = todos
      todos = [...rest, first]
    },
    prepend() {
      todos = [
        { id: 0, text: 'stretch' },
