    dropSecond() {
      todos = todos.filter(todo => todo.id !== 2)
    },
  }
  return (
    <ul data-testid="todos">
      {todos.map(todo => (
        <li key={todo.id} data-id={todo.id}>
          <span className="text">{todo.text}</span>
        </li>
      ))}
    </ul>
  )
}

